pub fn int_le(a: Int, b: Int) -> bool {
    match int_compare(a, b) {
    Ordering::Less => true,
    Ordering::Equal => true,
    Ordering::Greater => false,
}
}

pub fn int_gt(a: Int, b: Int) -> bool {
    match int_compare(a, b) {
    Ordering::Less => false,
    Ordering::Equal => false,
    Ordering::Greater => true,
}
}

pub fn int_ge(a: Int, b: Int) -> bool {
    match int_compare(a, b) {
    Ordering::Greater => true,
    Ordering::Equal => true,
    Ordering::Less => false,
}
}

